// ❌ OLD: Manual enter/exit choreography. You must animate the old
// element out, wait, swap the DOM, then animate the new element in —
// with setTimeout timing that drifts and double-animation on fast paths.
function swap(oldEl, newEl) {
  oldEl.classList.add('exit'); // ❌ OLD: animate old out
  setTimeout(() => {
    oldEl.remove();
    document.body.append(newEl);
    newEl.classList.add('enter'); // ❌ OLD: animate new in after 300ms
  }, 300);
}

// Fragile: the exit animation may be interrupted, the timing may
// overlap with user interaction, and there is no single visual
// snapshot guaranteeing the two states align.

// ✅ NEW: startViewTransition captures the old page, runs the DOM
// update, captures the new page, and crossfades between the snapshots
// — no manual enter/exit choreography or setTimeout timing.
async function swap() {
  const t = document.startViewTransition(() => {
    // ✅ NEW: the callback performs the real DOM change
    swapDOM();
  });

  await t.finished; // ✅ NEW: resolves when the transition completes
}

